/* expat_config.h for the Expat copy bundled with GenomeTools.

   This file is not part of the Expat distribution (there it is generated by
   configure or CMake). It is written by hand, because GenomeTools compiles
   the Expat sources directly from its own Makefile. */

#ifndef EXPAT_CONFIG_H
#define EXPAT_CONFIG_H 1

/* 1234 = little endian, 4321 = big endian */
#if defined(__BYTE_ORDER__) && defined(__ORDER_BIG_ENDIAN__) \
    && __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
#  define BYTEORDER 4321
#else
#  define BYTEORDER 1234
#endif

/* Source of entropy for the hash salt. On Windows Expat uses rand_s() on its
   own, everywhere else /dev/urandom is available. */
#ifndef _WIN32
#  define XML_DEV_URANDOM 1
#endif

/* Use the printf() family of the Microsoft C runtime when compiling with
   MinGW, like the build systems of Expat do (they pass
   -D__USE_MINGW_ANSI_STDIO=0). Otherwise the format strings Expat chooses in
   internal.h do not match the argument types on 64-bit Windows. Must be
   defined before the first system header is included. */
#ifdef __MINGW32__
#  undef __USE_MINGW_ANSI_STDIO
#  define __USE_MINGW_ANSI_STDIO 0
#endif

/* Number of bytes of context kept around the current parse point. */
#define XML_CONTEXT_BYTES 1024

/* Support for general entities. */
#define XML_GE 1

/* XML_DTD (parameter entities / external DTD subset) and XML_NS (namespace
   processing) are intentionally not defined, GenomeTools does not need them
   and the previously bundled Expat 2.0.1 was built without them, too. */

#endif /* EXPAT_CONFIG_H */
